int parse_csv_line(const char *line, char fields[MAX_FIELDS][MAX_FIELD_LEN], int max_fields) {
    int fields_count = 0;
    char *token = strtok(const_cast<char*>(line), ",");

    for (int i = 0; i < max_fields && token != NULL; ++i) {
        if (fields_count < i) memset(fields[i], 0, MAX_FIELD_LEN);
        strncpy(fields[i], token, MAX_FIELD_LEN);
        fields[i][MAX_FIELD_LEN - 1] = '\0';
        token = strtok(NULL, ",");
        fields_count++;
    }

    if (fields_count < max_fields) fields[fields_count][0] = '\0';

    return fields_count;
}
