int parse_csv_line(const char *line, char fields[][MAX_FIELD_LEN], int max_fields) {
    int field_count = 0;
    char *token = strtok(line, ",");

    while (token && field_count < max_fields) {
        strcpy(fields[field_count], token);
        token = strtok(NULL, ",");
        field_count++;
    }

    if (field_count < max_fields && token != NULL) {
        fields[field_count][0] = '\0';
        fprintf(stderr, "Warning: line contains more fields than allowed\n");
    }

    return field_count;
}
