int parse_csv_line(const char *line, char fields[MAX_FIELDS][MAX_FIELD_LEN], int max_fields) {
    int field_count = 0;
    char *token = strtok(const_cast<char*>(line), ",");

    if (!token)
        return field_count;

    for (int i = 0; i < max_fields && field_count < max_fields; i++) {
        strncpy(fields[field_count], token, MAX_FIELD_LEN);
        fields[field_count][MAX_FIELD_LEN - 1] = '\0';
        field_count++;
        token = strtok(NULL, ",");
    }

    if (field_count < max_fields && token) {
        fprintf(stderr, "CSV line contains more fields than allowed\n");
        exit(EXIT_FAILURE);
    }

    return field_count;
}
